<?php namespace ProcessWire;

/**
 * Video Files: class names of UIkit 3 for videos on the website
 *
 * Choose it in the settings of the module "Video Files" (CSS framework of the website), or
 * for a single video: $video->render([ 'framework' => 'uikit3' ]). The module does not load
 * UIkit. Your website has to include its stylesheet.
 *
 * To change this profile, do not edit this file: it is replaced with every update of the
 * module. Create /site/templates/selfhostedvideo/frameworks/uikit3.php instead, which is then used
 * in place of this file. It can be a copy of this file, or name only what it changes:
 *
 *     return array(
 *         'extends' => 'uikit3',
 *         'parts' => array(
 *             'caption' => 'uk-text-center uk-margin-small-top',
 *             'title' => false,  // false: this part is left to the module again
 *         ),
 *     );
 *
 * A file under another name (bootstrap5.php, mysite.php) is a profile of its own.
 *
 * THE FORMAT
 *
 * `title`    The name shown in the module settings.
 * `extends`  Optional. The name of a profile to build on: its parts and stylesheets are
 *            taken over, and the parts named here take the place of its parts of the same name.
 * `css`      Optional. The name of a stylesheet in the same folder as this file. It is loaded
 *            after the stylesheet of the module, for what class names alone cannot do.
 * `parts`    What each part of the markup gets. The README lists all parts. A part is given
 *            either class names:
 *
 *                'caption' => 'uk-margin-small-top',
 *
 *            or an array, where every entry is optional:
 *
 *                'chapter' => array(
 *                    'class'   => 'uk-link-heading',              // class names
 *                    'current' => 'uk-text-bold',                 // class names while this chapter is being played
 *                    'attrs'   => array('data-foo' => 'bar'),     // more attributes
 *                    'look'    => false,                          // false: without the look of the module
 *                ),
 *
 *            A part that gets class names loses the look the module would give it (colours,
 *            borders, margins, font weights), so that the framework decides. To keep the look
 *            of the module and add to it, set 'look' => true. To drop the look of the module
 *            without adding class names, set 'look' => false.
 *
 * The parts keep the class names of the module (shv-video__overlay and so on) and what makes
 * them work: where an overlay sits, that its text grows with the picture, the focus rings
 * on the picture.
 *
 * This file is part of the FieldtypeSelfHostedVideo module for ProcessWire 3.x
 *
 */

if(!defined("PROCESSWIRE")) die();

return array(

	'title' => 'UIkit 3',

	'css' => 'uikit3.css',

	'parts' => array(

		// a video with controls
		'player' => 'uk-margin',

		// overlays: text and links on the picture, in UIkit's secondary and default background
		'overlay' => 'uk-border-rounded',
		'overlay-dark' => 'uk-background-secondary uk-light',
		'overlay-light' => 'uk-background-default uk-text-emphasis',

		// the list of chapters below the video
		'chapters' => 'uk-margin-small-top',
		'chapters-label' => 'uk-text-bold uk-margin-small-bottom',
		'chapter-list' => 'uk-list uk-list-divider',
		'chapter-item' => array('current' => 'uk-active'),
		'chapter' => array('class' => 'uk-link-heading', 'current' => 'uk-text-bold'),

		// title, duration and description below the video
		'caption' => 'uk-margin-small-top',
		'title' => 'uk-text-bold uk-text-large',
		'meta' => 'uk-text-small', // not uk-text-meta: its grey is too pale to read (2.8:1)
		'description' => 'uk-text-small',

		// More about the video (the custom fields, in a box that opens): a grey tile of UIkit, with
		// UIkit's description list in it. The box stays the browser's own details element: UIkit's
		// accordion needs its script and another markup.
		'info' => 'uk-tile uk-tile-muted uk-padding-small uk-border-rounded uk-margin-top',
		'info-list' => 'uk-description-list uk-margin-small-top uk-margin-remove-bottom',

		// The transcript (the text of the captions, in a box that opens): a grey tile as well
		'transcript' => 'uk-tile uk-tile-muted uk-padding-small uk-border-rounded uk-margin-top',
		'transcript-body' => 'uk-margin-small-top',

		// The two buttons on the picture (full screen, pause of a background video) keep the look
		// of the module: white on black with a white ring, which can be seen on any picture.
		// UIkit's icon button is grey on light grey. To use it all the same:
		// 'fullscreen' => 'uk-icon-button',
		// 'toggle' => 'uk-icon-button',
	),
);
